declare(strict_types=1); require __DIR__.'/app/bootstrap.php';
if(!users_exist($pdo)){ header('Location: /first-admin.php'); exit; }
$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$email=strtolower(trim($_POST['email']??''));try{rate_limit_enforce($pdo,$config,'login_ip',rate_limit_subject_ip(),20,900);rate_limit_enforce($pdo,$config,'login_email',rate_limit_subject_email($email),8,900);$s=$pdo->prepare('SELECT id,password_hash FROM users WHERE email=? AND status="active"');$s->execute([$email]);$u=$s->fetch();if($u&&$u['password_hash']&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];header('Location:'.post_login_destination());exit;}$error='Invalid email or password.';}catch(RateLimitExceeded $e){$error=rate_limit_web_error($e);}}
